from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while q:
                x, y = q.popleft()
                component.append((x, y))
                touches_edge |= x == 0 or x == h - 1 or y == 0 or y == w - 1
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == background and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not touches_edge:
                for x, y in component:
                    out[x][y] = 4
    return out

